214 :                     bigInd = i;
215 :                 }
216 :             }
217 : 
218 :             // Default convergence check.
219 :             boolean stop = 2 * (fX - fVal) <=
220 :                 (relativeThreshold * (FastMath.abs(fX) + FastMath.abs(fVal)) +
221 :                  absoluteThreshold);
222 : 
223 :             final PointValuePair previous = new PointValuePair(x1, fX);
224 :             final PointValuePair current = new PointValuePair(x, fVal);
225 :             if (!stop) { // User-defined stopping criteria.
226 :                 if (checker != null) {
227 :                     stop = checker.converged(iter, previous, current);
228 :                 }
229 :             }
230 :             if (stop) {
231 :                 if (goal == GoalType.MINIMIZE) {
232 :                     return (fVal < fX) ? current : previous;
233 :                 } else {
234 :                     return (fVal > fX) ? current : previous;
235 :                 }
236 :             }
237 : 
238 :             final double[] d = new double[n];
239 :             final double[] x2 = new double[n];
240 :             for (int i = 0; i < n; i++) {
241 :                 d[i] = x[i] - x1[i];
242 :                 x2[i] = 2 * x[i] - x1[i];
243 :             }
244 : 
245 :             x1 = x.clone();
246 :             fX2 = computeObjectiveValue(x2);
247 : 
248 :             if (fX > fX2) {
249 :                 double t = 2 * (fX + fX2 - 2 * fVal);
250 :                 double temp = fX - fVal - delta;
251 :                 t *= temp * temp;
252 :                 temp = fX - fX2;
253 :                 t -= delta * temp * temp;
254 : 
255 :                 if (t < 0.0) {
256 :                     final UnivariatePointValuePair optimum = line.search(x, d);
257 :                     fVal = optimum.getValue();
258 :                     alphaMin = optimum.getPoint();
259 :                     final double[][] result = newPointAndDirection(x, d, alphaMin);
260 :                     x = result[0];
261 : 
262 :                     final int lastInd = n - 1;
263 :                     direc[bigInd] = direc[lastInd];
264 :                     direc[lastInd] = result[1];
265 :                 }
266 :             }
267 :         }
268 :     }"

