" 79 :     @Override
 80 :     public PointVectorValuePair doOptimize() {
 81 :         checkParameters();
 82 : 
 83 :         final ConvergenceChecker<PointVectorValuePair> checker
 84 :             = getConvergenceChecker();
 85 : 
 86 :         // Computation will be useless without a checker (see "for-loop").
 87 :         if (checker == null) {
 88 :             throw new NullArgumentException();
 89 :         }
 90 : 
 91 :         final double[] targetValues = getTarget();
 92 :         final int nR = targetValues.length; // Number of observed data.
 93 : 
 94 :         final RealMatrix weightMatrix = getWeight();
 95 :         // Diagonal of the weight matrix.
 96 :         final double[] residualsWeights = new double[nR];
 97 :         for (int i = 0; i < nR; i++) {
 98 :             residualsWeights[i] = weightMatrix.getEntry(i, i);
 99 :         }
100 : 
101 :         final double[] currentPoint = getStartPoint();
102 :         final int nC = currentPoint.length;
103 : 
104 :         // iterate until convergence is reached
105 :         PointVectorValuePair current = null;
106 :         int iter = 0;
107 :         for (boolean converged = false; !converged;) {
108 :             ++iter;
109 : 
110 :             // evaluate the objective function and its jacobian
111 :             PointVectorValuePair previous = current;
112 :             // Value of the objective function at "currentPoint".
113 :             final double[] currentObjective = computeObjectiveValue(currentPoint);
114 :             final double[] currentResiduals = computeResiduals(currentObjective);
115 :             final RealMatrix weightedJacobian = computeWeightedJacobian(currentPoint);
116 :             current = new PointVectorValuePair(currentPoint, currentObjective);
117 : 
118 :             // build the linear problem
119 :             final double[]   b = new double[nC];
120 :             final double[][] a = new double[nC][nC];
121 :             for (int i = 0; i < nR; ++i) {
122 : 
123 :                 final double[] grad   = weightedJacobian.getRow(i);
124 :                 final double weight   = residualsWeights[i];
125 :                 final double residual = currentResiduals[i];
126 : 
127 :                 // compute the normal equation
128 :                 final double wr = weight * residual;
129 :                 for (int j = 0; j < nC; ++j) {
130 :                     b[j] += wr * grad[j];
131 :                 }
132 : 
133 :                 // build the contribution matrix for measurement i
134 :                 for (int k = 0; k < nC; ++k) {
135 :                     double[] ak = a[k];
136 :                     double wgk = weight * grad[k];
137 :                     for (int l = 0; l < nC; ++l) {
138 :                         ak[l] += wgk * grad[l];
139 :                     }
140 :                 }
141 :             }
142 : 
143 :             try {
144 :                 // solve the linearized least squares problem
145 :                 RealMatrix mA = new BlockRealMatrix(a);
146 :                 DecompositionSolver solver = useLU ?
147 :                         new LUDecomposition(mA).getSolver() :
148 :                         new QRDecomposition(mA).getSolver();
149 :                 final double[] dX = solver.solve(new ArrayRealVector(b, false)).toArray();
150 :                 // update the estimated parameters
151 :                 for (int i = 0; i < nC; ++i) {
152 :                     currentPoint[i] += dX[i];
153 :                 }
154 :             } catch (SingularMatrixException e) {
155 :                 throw new ConvergenceException(LocalizedFormats.UNABLE_TO_SOLVE_SINGULAR_PROBLEM);
156 :             }
157 : 
158 :             // Check convergence.
159 :             if (previous != null) {
160 :                 converged = checker.converged(iter, previous, current);
161 :                 if (converged) {
162 :                     setCost(computeCost(currentResiduals));
163 :                     return current;
164 :                 }
165 :             }
166 :         }
167 :         // Must never happen.
168 :         throw new MathInternalError();
169 :     }"

