"283 :     @Override
284 :     protected PointVectorValuePair doOptimize() {
285 :         checkParameters();
286 : 
287 :         final int nR = getTarget().length; // Number of observed data.
288 :         final double[] currentPoint = getStartPoint();
289 :         final int nC = currentPoint.length; // Number of parameters.
290 : 
291 :         // arrays shared with the other private methods
292 :         solvedCols  = FastMath.min(nR, nC);
293 :         diagR       = new double[nC];
294 :         jacNorm     = new double[nC];
295 :         beta        = new double[nC];
296 :         permutation = new int[nC];
297 :         lmDir       = new double[nC];
298 : 
299 :         // local point
300 :         double   delta   = 0;
301 :         double   xNorm   = 0;
302 :         double[] diag    = new double[nC];
303 :         double[] oldX    = new double[nC];
304 :         double[] oldRes  = new double[nR];
305 :         double[] oldObj  = new double[nR];
306 :         double[] qtf     = new double[nR];
307 :         double[] work1   = new double[nC];
308 :         double[] work2   = new double[nC];
309 :         double[] work3   = new double[nC];
310 : 
311 :         final RealMatrix weightMatrixSqrt = getWeightSquareRoot();
312 : 
313 :         // Evaluate the function at the starting point and calculate its norm.
314 :         double[] currentObjective = computeObjectiveValue(currentPoint);
315 :         double[] currentResiduals = computeResiduals(currentObjective);
316 :         PointVectorValuePair current = new PointVectorValuePair(currentPoint, currentObjective);
317 :         double currentCost = computeCost(currentResiduals);
318 : 
319 :         // Outer loop.
320 :         lmPar = 0;
321 :         boolean firstIteration = true;
322 :         int iter = 0;
323 :         final ConvergenceChecker<PointVectorValuePair> checker = getConvergenceChecker();
324 :         while (true) {
325 :             ++iter;
326 :             final PointVectorValuePair previous = current;
327 : 
328 :             // QR decomposition of the jacobian matrix
329 :             qrDecomposition(computeWeightedJacobian(currentPoint));
330 : 
331 :             weightedResidual = weightMatrixSqrt.operate(currentResiduals);
332 :             for (int i = 0; i < nR; i++) {
333 :                 qtf[i] = weightedResidual[i];
334 :             }
335 : 
336 :             // compute Qt.res
337 :             qTy(qtf);
338 : 
339 :             // now we don't need Q anymore,
340 :             // so let jacobian contain the R matrix with its diagonal elements
341 :             for (int k = 0; k < solvedCols; ++k) {
342 :                 int pk = permutation[k];
343 :                 weightedJacobian[k][pk] = diagR[pk];
344 :             }
345 : 
346 :             if (firstIteration) {
347 :                 // scale the point according to the norms of the columns
348 :                 // of the initial jacobian
349 :                 xNorm = 0;
350 :                 for (int k = 0; k < nC; ++k) {
351 :                     double dk = jacNorm[k];
352 :                     if (dk == 0) {
353 :                         dk = 1.0;
354 :                     }
355 :                     double xk = dk * currentPoint[k];
356 :                     xNorm  += xk * xk;
357 :                     diag[k] = dk;
358 :                 }
359 :                 xNorm = FastMath.sqrt(xNorm);
360 : 
361 :                 // initialize the step bound delta
362 :                 delta = (xNorm == 0) ? initialStepBoundFactor : (initialStepBoundFactor * xNorm);
363 :             }
364 : 
365 :             // check orthogonality between function vector and jacobian columns
366 :             double maxCosine = 0;
367 :             if (currentCost != 0) {
368 :                 for (int j = 0; j < solvedCols; ++j) {
369 :                     int    pj = permutation[j];
370 :                     double s  = jacNorm[pj];
371 :                     if (s != 0) {
372 :                         double sum = 0;
373 :                         for (int i = 0; i <= j; ++i) {
374 :                             sum += weightedJacobian[i][pj] * qtf[i];
375 :                         }
376 :                         maxCosine = FastMath.max(maxCosine, FastMath.abs(sum) / (s * currentCost));
377 :                     }
378 :                 }
379 :             }
380 :             if (maxCosine <= orthoTolerance) {
381 :                 // Convergence has been reached.
382 :                 setCost(currentCost);
383 :                 return current;
384 :             }
385 : 
386 :             // rescale if necessary
387 :             for (int j = 0; j < nC; ++j) {
388 :                 diag[j] = FastMath.max(diag[j], jacNorm[j]);
389 :             }
390 : 
391 :             // Inner loop.
392 :             for (double ratio = 0; ratio < 1.0e-4;) {
393 : 
394 :                 // save the state
395 :                 for (int j = 0; j < solvedCols; ++j) {
396 :                     int pj = permutation[j];
397 :                     oldX[pj] = currentPoint[pj];
398 :                 }
399 :                 final double previousCost = currentCost;
400 :                 double[] tmpVec = weightedResidual;
401 :                 weightedResidual = oldRes;
402 :                 oldRes    = tmpVec;
403 :                 tmpVec    = currentObjective;
404 :                 currentObjective = oldObj;
405 :                 oldObj    = tmpVec;
406 : 
407 :                 // determine the Levenberg-Marquardt parameter
408 :                 determineLMParameter(qtf, delta, diag, work1, work2, work3);
409 : 
410 :                 // compute the new point and the norm of the evolution direction
411 :                 double lmNorm = 0;
412 :                 for (int j = 0; j < solvedCols; ++j) {
413 :                     int pj = permutation[j];
414 :                     lmDir[pj] = -lmDir[pj];
415 :                     currentPoint[pj] = oldX[pj] + lmDir[pj];
416 :                     double s = diag[pj] * lmDir[pj];
417 :                     lmNorm  += s * s;
418 :                 }
419 :                 lmNorm = FastMath.sqrt(lmNorm);
420 :                 // on the first iteration, adjust the initial step bound.
421 :                 if (firstIteration) {
422 :                     delta = FastMath.min(delta, lmNorm);
423 :                 }
424 : 
425 :                 // Evaluate the function at x + p and calculate its norm.
426 :                 currentObjective = computeObjectiveValue(currentPoint);
427 :                 currentResiduals = computeResiduals(currentObjective);
428 :                 current = new PointVectorValuePair(currentPoint, currentObjective);
429 :                 currentCost = computeCost(currentResiduals);
430 : 
431 :                 // compute the scaled actual reduction
432 :                 double actRed = -1.0;
433 :                 if (0.1 * currentCost < previousCost) {
434 :                     double r = currentCost / previousCost;
435 :                     actRed = 1.0 - r * r;
436 :                 }
437 : 
438 :                 // compute the scaled predicted reduction
439 :                 // and the scaled directional derivative
440 :                 for (int j = 0; j < solvedCols; ++j) {
441 :                     int pj = permutation[j];
442 :                     double dirJ = lmDir[pj];
443 :                     work1[j] = 0;
444 :                     for (int i = 0; i <= j; ++i) {
445 :                         work1[i] += weightedJacobian[i][pj] * dirJ;
446 :                     }
447 :                 }
448 :                 double coeff1 = 0;
449 :                 for (int j = 0; j < solvedCols; ++j) {
450 :                     coeff1 += work1[j] * work1[j];
451 :                 }
452 :                 double pc2 = previousCost * previousCost;
453 :                 coeff1 = coeff1 / pc2;
454 :                 double coeff2 = lmPar * lmNorm * lmNorm / pc2;
455 :                 double preRed = coeff1 + 2 * coeff2;
456 :                 double dirDer = -(coeff1 + coeff2);
457 : 
458 :                 // ratio of the actual to the predicted reduction
459 :                 ratio = (preRed == 0) ? 0 : (actRed / preRed);
460 : 
461 :                 // update the step bound
462 :                 if (ratio <= 0.25) {
463 :                     double tmp =
464 :                         (actRed < 0) ? (0.5 * dirDer / (dirDer + 0.5 * actRed)) : 0.5;
465 :                         if ((0.1 * currentCost >= previousCost) || (tmp < 0.1)) {
466 :                             tmp = 0.1;
467 :                         }
468 :                         delta = tmp * FastMath.min(delta, 10.0 * lmNorm);
469 :                         lmPar /= tmp;
470 :                 } else if ((lmPar == 0) || (ratio >= 0.75)) {
471 :                     delta = 2 * lmNorm;
472 :                     lmPar *= 0.5;
473 :                 }
474 : 
475 :                 // test for successful iteration.
476 :                 if (ratio >= 1.0e-4) {
477 :                     // successful iteration, update the norm
478 :                     firstIteration = false;
479 :                     xNorm = 0;
480 :                     for (int k = 0; k < nC; ++k) {
481 :                         double xK = diag[k] * currentPoint[k];
482 :                         xNorm += xK * xK;
483 :                     }
484 :                     xNorm = FastMath.sqrt(xNorm);
485 : 
486 :                     // tests for convergence.
487 :                     if (checker != null) {
488 :                         // we use the vectorial convergence checker
489 :                         if (checker.converged(iter, previous, current)) {
490 :                             setCost(currentCost);
491 :                             return current;
492 :                         }
493 :                     }
494 :                 } else {
495 :                     // failed iteration, reset the previous values
496 :                     currentCost = previousCost;
497 :                     for (int j = 0; j < solvedCols; ++j) {
498 :                         int pj = permutation[j];
499 :                         currentPoint[pj] = oldX[pj];
500 :                     }
501 :                     tmpVec    = weightedResidual;
502 :                     weightedResidual = oldRes;
503 :                     oldRes    = tmpVec;
504 :                     tmpVec    = currentObjective;
505 :                     currentObjective = oldObj;
506 :                     oldObj    = tmpVec;
507 :                     // Reset "current" to previous values.
508 :                     current = new PointVectorValuePair(currentPoint, currentObjective);
509 :                 }
510 : 
511 :                 // Default convergence criteria.
512 :                 if ((FastMath.abs(actRed) <= costRelativeTolerance &&
513 :                      preRed <= costRelativeTolerance &&
514 :                      ratio <= 2.0) ||
515 :                     delta <= parRelativeTolerance * xNorm) {
516 :                     setCost(currentCost);
517 :                     return current;
518 :                 }
519 : 
520 :                 // tests for termination and stringent tolerances
521 :                 // (2.2204e-16 is the machine epsilon for IEEE754)
522 :                 if ((FastMath.abs(actRed) <= 2.2204e-16) && (preRed <= 2.2204e-16) && (ratio <= 2.0)) {
523 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_COST_RELATIVE_TOLERANCE,
524 :                                                    costRelativeTolerance);
525 :                 } else if (delta <= 2.2204e-16 * xNorm) {
526 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_PARAMETERS_RELATIVE_TOLERANCE,
527 :                                                    parRelativeTolerance);
528 :                 } else if (maxCosine <= 2.2204e-16)  {
529 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_ORTHOGONALITY_TOLERANCE,
530 :                                                    orthoTolerance);
531 :                 }
532 :             }
533 :         }
534 :     }"

